import { useEffect, useState } from "react";
import axios from "axios";

import Navbar from "./Components/Navbar/Navbar";
import Item from "./Components/Item/Item";

function App() {
  const [foods, setFoods] = useState([]);
  const [cart, setCart] = useState([]);

  // Fetch food items
  useEffect(() => {
    axios
      .get("http://localhost:5000/foods")
      .then((res) => setFoods(res.data))
      .catch((err) => console.log("Error fetching foods:", err));
  }, []);

  // Add to cart (safe version)
  const addToCart = (item) => {
    setCart((prev) => [...prev, item]);
  };

  // Group cart items (for quantity display)
  const groupedCart = Object.values(
    cart.reduce((acc, item) => {
      if (!acc[item._id]) {
        acc[item._id] = { ...item, qty: 1 };
      } else {
        acc[item._id].qty += 1;
      }
      return acc;
    }, {}),
  );

  // Calculate total
  const total = groupedCart.reduce(
    (sum, item) => sum + item.price * item.qty,
    0,
  );

  // Place order
  const placeOrder = () => {
    const user = JSON.parse(localStorage.getItem("user"));

    if (!user) {
      alert("Please login first");
      return;
    }

    if (cart.length === 0) {
      alert("Cart is empty!");
      return;
    }

    axios
      .post("http://localhost:5000/orders", {
        userEmail: user.email,
        items: groupedCart,
        total,
      })
      .then(() => {
        alert(`Order placed successfully! Total: ₹${total}`);
        setCart([]);
      })
      .catch((err) => {
        console.log(err);

        alert("Failed to place order");
      });
  };

  return (
    <div>
      {/* Navbar */}
      <Navbar cartCount={cart.length} />

      <div style={{ padding: 20 }}>
        <h2>Menu</h2>

        {/* Food Items */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))",
            gap: "20px",
          }}
        >
          {foods.map((f) => (
            <Item
              key={f._id}
              name={f.name}
              price={f.price}
              image={f.image}
              addToCart={() => addToCart(f)}
            />
          ))}
        </div>

        {/* Cart Section */}
        <h2 style={{ marginTop: "30px" }}>Cart</h2>

        {groupedCart.length === 0 ? (
          <p>No items in cart</p>
        ) : (
          groupedCart.map((item) => (
            <p key={item._id}>
              {item.name} × {item.qty} = ₹{item.price * item.qty}
            </p>
          ))
        )}

        {/* Total */}
        <h3>Total: ₹{total}</h3>

        {/* Buttons */}
        <button onClick={placeOrder}>Place Order</button>
        <button onClick={() => setCart([])} style={{ marginLeft: "10px" }}>
          Clear Cart
        </button>
      </div>
    </div>
  );
}

export default App;
